fill(box((0,0),(1,1)),f);fill(box((1,0),(2,1)),f);fill(box((2,0),(3,1)),f);
fill(box((3,1),(4,2)),f);fill(box((4,1),(5,2)),f);fill(box((5,1),(6,2)),f);
